class Solution {
private:
    pair<long long, long long> countAndSum(int target, vector<int>& nums, vector<long long>& prefix, vector<long long>& pprefix) {
        long long count = 0, total = 0;
        int left = 0;
        int n = nums.size();
        for (int i = 1; i <= n; i++) {
            while (prefix[i] - prefix[left] > target) {
                left++;
            }
            int num_subarrays = i - left;
            count += num_subarrays;
            long long sum_prefix = pprefix[i] - pprefix[left];
            total += (long long)num_subarrays * prefix[i] - sum_prefix;
        }
        return {count, total};
    }

    long long sumOfFirstK(int K, vector<int>& nums, vector<long long>& prefix, vector<long long>& pprefix) {
        int low = 1, high = 100000;
        while (low < high) {
            int mid = low + (high - low) / 2;
            if (countAndSum(mid, nums, prefix, pprefix).first >= K) {
                high = mid;
            } else {
                low = mid + 1;
            }
        }
        auto [count, total] = countAndSum(low, nums, prefix, pprefix);
        return total - (count - K) * low;
    }

public:
    int rangeSum(vector<int>& nums, int n, int left, int right) {
        int MOD = 1000000007;
        vector<long long> prefix(n + 1, 0);
        vector<long long> pprefix(n + 1, 0);
        for (int i = 0; i < n; i++) {
            prefix[i + 1] = prefix[i] + nums[i];
            pprefix[i + 1] = pprefix[i] + prefix[i];
        }
        long long ans = (sumOfFirstK(right, nums, prefix, pprefix) - sumOfFirstK(left - 1, nums, prefix, pprefix)) % MOD;
        if (ans < 0) ans += MOD;
        return ans;
    }
};
